<?php require_once __DIR__.'/inc/config.php'; require_once __DIR__.'/inc/auth.php'; require_admin(); $orders=read_orders(); $i=(int)($_GET['i']??$_POST['index']??-1); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'&&isset($orders[$i])){$orders[$i]['customer']=trim($_POST['customer']??'');$orders[$i]['tableNumber']=trim($_POST['tableNumber']??'');$orders[$i]['paymentOption']=trim($_POST['paymentOption']??'');$orders[$i]['status']=$_POST['status']??($orders[$i]['status']??'Pending');$orders[$i]['items']=json_decode($_POST['items_json']??'[]',true)?:($orders[$i]['items']??[]);$orders[$i]['name']=implode(', ',array_map(fn($x)=>$x['name'].' x '.($x['qty']??1),$orders[$i]['items']));$orders[$i]['price']=array_reduce($orders[$i]['items'],fn($s,$x)=>$s+(float)($x['price']??0)*(int)($x['qty']??1),0);save_orders($orders);$message='Order updated.';} $o=$orders[$i]??null; admin_header('Edit Order'); ?><section class="admin-panel"><h2>Edit order</h2><?php if(!$o):?><p>Order not found.</p><?php else:?><p><?=e($message)?></p><form class="admin-form" method="post"><input type="hidden" name="index" value="<?=$i?>"><label>Customer<input name="customer" value="<?=e($o['customer']??'')?>" required></label><label>Table<input name="tableNumber" value="<?=e($o['tableNumber']??'')?>" required></label><label>Payment<input name="paymentOption" value="<?=e($o['paymentOption']??'Cash')?>"></label><label>Status<select name="status"><?php foreach(['Pending','Preparing','Ready','Completed'] as $s):?><option <?=$s===($o['status']??'Pending')?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><label>Items JSON <textarea name="items_json" rows="8"><?=e(json_encode($o['items']??[],JSON_PRETTY_PRINT))?></textarea></label><button class="btn">Save order</button></form><?php endif;?><p><a href="admin.php">Back to orders</a></p></section><?php admin_footer();?>
